args.command:
cd /workspace/w; export P=http://127.0.0.1:43307; T=http://127.0.0.1:3000
login() { curl -s --max-time 10 -x $P -c $W/$1.jar -H 'Content-Type: application/json' -d "{\"username\":\"$1\",\"password\":\"$1-password\"}" $T/app/login >/dev/null; printf "%-6s " $1; curl -s --max-time 10 -x $P -b $W/$1.jar -w ' [%{http_code}]\n' $T/app/api/me; }
W=/workspace/w; login alice; login bob; login admin

cat > /workspace/w/t.sh <<'SH'
#!/bin/bash
P=http://127.0.0.1:43307; T=http://127.0.0.1:3000; W=/workspace/w; E=$W/evidence
mkd=$(date +%s%N)
i=0
# t <slug> <curl args...>
t() {
  local slug="$1"; shift
  i=$((i+1)); local f; f=$(printf "%s/%02d-%s" "$E" "$i" "$slug")
  { printf '### %s\n' "$slug"
    printf 'REQUEST: curl -sS -x %s' "$P"; for a in "$@"; do case "$a" in *" "*) printf " '%s'" "$a";; *) printf ' %s' "$a";; esac; done; printf '\n'
    curl -sS -D - --max-time 15 "$@" ; printf '\n---\n'
  } > "$f.txt" 2>&1
  printf '%-64s | %s\n' "$slug" "$(grep -m1 -E '^HTTP/' "$f.txt" | tr -d '\r') | $(sed -n '/^HTTP/,$p' "$f.txt" | grep -m1 -v -E '^(HTTP|content-|cache-|date|connection|transfer|vary|etag|set-cookie)' | tr -d '\r' | head -c 220)"
}
mk() { head -c 8 /dev/urandom | od -An -tx1 | tr -d ' \n'; }
newid() { printf '%s' "$1" | sed -n 's/.*"id":"\([^"]*\)".*/\1/p'; }
SH
cat /workspace/w/t.sh

cat > /workspace/w/t.sh <<'SH'
#!/bin/bash
P=http://127.0.0.1:43307; T=http://127.0.0.1:3000; W=/workspace/w; E=$W/evidence
CNT=$W/.cnt
t() {
  local slug="$1"; shift
  local n; n=$(cat "$CNT" 2>/dev/null || echo 0); n=$((n+1)); echo "$n" > "$CNT"
  local f; f=$(printf "%s/%03d-%s" "$E" "$n" "$slug")
  { printf '### %03d %s\n' "$n" "$slug"
    printf 'REQUEST: curl -sS -x %s' "$P"; for a in "$@"; do case "$a" in *" "*) printf " '%s'" "$a";; *) printf ' %s' "$a";; esac; done; printf '\n'
    curl -sS -D - --max-time 15 -x "$P" "$@"; printf '\n---\n'
  } > "$f.txt" 2>&1
  local code=$(grep -m1 -E '^HTTP/' "$f.txt" | tr -d '\r')
  local body=$(sed -n '/^\r*$/,$p' "$f.txt" | grep -v '^$' | tr -d '\r' | head -c 200)
  printf '%-62s | %-24s | %s\n' "$slug" "$code" "$body"
}
mk() { head -c 8 /dev/urandom | od -An -tx1 | tr -d ' \n'; }
newid() { printf '%s' "$1" | sed -n 's/.*"id":"\([^"]*\)".*/\1/p'; }
SH
echo ok
